import { Controller, Get, Post, Req } from '@nestjs/common';
import { Request } from 'express';
import { SubscribeMessageService } from './subscribe.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';

interface SubscribeMetaDataDto {
  pubsubname: string;
  route: string;
  topic: string;
  metadata?: Record<string, string>;
}

const topics = {
  topicTasks: process.env.TOPIC_PICKING_TASKS,
};

@Controller()
export class SubscribeController {
  public constructor(
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @Get('/dapr/subscribe')
  public async subscribeMetaData(): Promise<Array<SubscribeMetaDataDto>> {
    return [
      {
        metadata: {
          checkPointFrequencyPerPartition:
            await this.eventhubService.checkPointFrequencyTasks(),
        },
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicTasks}`,
        topic: this.eventhubService.topicTasks,
      },
    ];
  }

  @Post(`/${topics.topicTasks || 'topic-tasks'}`)
  public async receiveTaskMessage(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageTask(data);
    return 'OK';
  }
}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { ApiModule } from 'src/api/api.module';
import { EventHubModule } from 'src/config/eventhub/eventhub.module';
import { RedisConfigModule } from 'src/config/redis/redis-store.module';
import { UpdateCacheModule } from 'src/update-cache/update-cache.module';
import { SubscribeController } from './subscribe.controller';
import { SubscribeMessageService } from './subscribe.service';
import { DaprConfigModule } from '@/config/dapr/dapr-config.module';
import { MutexManagerModule } from '@/mutex-manager/mutex-manager.module';
import { RedisProviderModule } from '@/providers/cache/redis/redis.module';
import { WorkersModule } from '@/workers/workers.module';

@Module({
  controllers: [SubscribeController],
  imports: [
    ConfigModule,
    RedisConfigModule,
    EventHubModule,
