    this.orderApiAppId = this.daprConfigService.orderApiAppId;
  }

  public async fetchMinSeqNum(
    requestDto: MinSeqNumberRequestDto,
  ): Promise<MinSeqNumberResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchMinSeqNum',
      object: requestDto.relatedOrder,
      plant: requestDto.plant,
      service: 'OrderApi',
    };

    const serviceMethod = `production-order/minSeqNumByPickingOrder/${requestDto.plant}/${requestDto.relatedOrder}`;
    const result = await invokeService<MinSeqNumberResponse>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        serviceAppId: this.orderApiAppId,
        serviceMethod,
        method: HttpMethod.GET,
      },
    );
    return result;
  }

  public async fetchMinSeqNumList(
    plant: number,
    relatedOrders: Array<string>,
  ): Promise<Record<string, string> | undefined> {
    const context: JobsLogContext = {
      method: 'fetchMinSeqNum',
      object: relatedOrders.toString(),
      plant,
      service: 'OrderApi',
    };
    const serviceMethod = `production-order/minSeqNumsByRelatedOrders/${plant}`;
    const result = await invokeService<Record<string, string>>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        data: { relatedOrders },
        method: HttpMethod.POST,
        serviceAppId: this.orderApiAppId,
        serviceMethod,
        useAxios: this.useAxios,
      },
    );
    return result;
  }

  public async fetchOrdersByDate(
    plant: number,
    date: Date,
  ): Promise<OrderResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchOrdersByDate',
      object: date.toString(),
      plant,
      service: 'OrderApi',
    };
    const serviceAppId = this.daprConfigService.orderApiInternalAppId;
    const serviceMethodSeqnum = `picking-order/orders-with-reschudeling-version-triggers/${plant}/${date.toISOString()}`;
    const url = `${serviceAppId}/${serviceMethodSeqnum}`;
    try {
      const response = await axios.get(url);

      const serverUTCDateTime = response.headers['date'];

      const result = response.data ?? [];
      const headers: Record<string, string> = {};
      headers['date'] = serverUTCDateTime;

      return {
        result: result as Array<PickingOrderList>,
        headers,
      };
    } catch (error) {
      this.customLogger.error(
        `Error in fetchOrdersByDate Plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

