    plantId: number,
  ): Promise<PlantConfigOrder> {
    const context: JobsLogContext = {
      method: 'fetchPlantConfigOrder',
      plant: plantId,
      service: 'OrderApi',
    };

    const result = await invokeService<PlantConfigOrder>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        serviceAppId: this.orderApiAppId,
        serviceMethod: `plant-config-order/${plantId}`,
        method: HttpMethod.GET,
        useAxios: this.useAxios,
