    const context: JobsLogContext = {
      method: 'fetchSebango',
      plant: pickingOrderIdsDto.plant,
      service: 'OrderApi',
    };

    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethodPath = `picking-order/getPickingOrderDetails`;
    const result = await invokeService<Array<PickingOrderList>>(
      {
        context,
        customLogger: this.customLogger,
        daprClient: this.daprClient,
      },
      {
        data: structuredClone(pickingOrderIdsDto),
        method: HttpMethod.POST,
        options: {
          headers: new RequestHeadersDto('application/json'),
