  public async getClosedShopOrderIds(
    plant: number,
    from: Date | undefined = undefined,
    to: Date | undefined = undefined,
  ): Promise<Array<string> | undefined> {
    const context: JobsLogContext = {
      method: 'getClosedShopOrderIds',
      object: 'plant',
      plant,
      service: 'OrderApi',
    };

    try {
      let serviceMethodSeqnum = `picking-order/closed-picking-orders/${plant}`;
      if (from) {
        serviceMethodSeqnum += `?from=${from.toISOString()}`;
      }
      if (to) {
        serviceMethodSeqnum += `&to=${to.toISOString()}`;
      }
      const response = await invokeService<Array<string>>(
        {
          context,
          customLogger: this.customLogger,
          daprClient: this.daprClient,
        },
        {
          serviceAppId: this.orderApiAppId,
          serviceMethod: serviceMethodSeqnum,
          method: HttpMethod.GET,
          useAxios: this.useAxios,
        },
      );
      return response;
    } catch (error) {
      this.customLogger.error(
        `Error in getClosedShopOrderIds: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

