      method: 'getShopOrdersCountByPlantList',
      object: 'plant',
      plant,
      service: 'OrderApi',
    };

    try {
      let serviceMethodSeqnum = `picking-order/count-by-plant`;
      if (plant) {
        serviceMethodSeqnum += `?plant=${plant}`;
