  public async getOrderIdsByOutboundListAndPlant(
    plant: number,
    outbounds: Array<string>,
  ): Promise<Record<string, Array<string>> | undefined> {
    const context: JobsLogContext = {
      method: 'getOrderIdsByOutboundListAndPlant',
      object: 'plant',
      plant,
      service: 'OrderApi',
    };
    const requestDto = {
      plant,
      outbounds,
    };
    try {
      const serviceMethodSeqnum = `picking-order/orders-by-plant-outbounds`;
      const response = await invokeService<Record<string, Array<string>>>(
        {
          context,
          customLogger: this.customLogger,
          daprClient: this.daprClient,
        },
        {
