#!/usr/bin/env node
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { UpdateCosmosStructure } from './update-cache/update-cosmos-structure';

/**
 *
 */
async function bootstrap(): Promise<void> {
  const appContext = await NestFactory.createApplicationContext(AppModule);
  const updateCosmosStructure = appContext.get(UpdateCosmosStructure);

  try {
    await updateCosmosStructure.updateCosmosStructure();
  } catch (error) {
    console.error('Error updating missing fields:', error);
  } finally {
    await appContext.close();
    process.exit(0);
  }
}
bootstrap();

