import {
  BulkOperationType,
  CosmosClient,
  CreateOperationInput,
  JSONObject,
  PatchOperation,
  ReplaceOperationInput,
} from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import pMap from 'p-map';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseConfigService } from '@/config/cosmos-db/cosmos.database.service';
import { OrderUpdate } from '@/interface/order-update';
import { PickingOrderList } from '@/interface/picking-order-list';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class CosmosDatabaseService {
  public static serializeDates(object: ShopOrder): JSONObject {
    return JSON.parse(
      JSON.stringify(object, (key, value) =>
        value instanceof Date ? value.toISOString() : value,
      ),
    );
  }

  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  public constructor(
    private readonly cosmosDatabasebService: CosmosDatabaseConfigService,
    private readonly customLogger: AppLogger,
  ) {
    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDatabasebService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosDatabasebService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosDatabasebService.cosmosDbContainer,
    );
  }

  public async upsertBatchShopOrders(
    partitionKeyField: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'upsertBatchShopOrders',
      plant: shopOrders[0].plant,
      service: 'CosmosDatabaseService',
    };
    try {
      const upsertPromises = shopOrders.map((order) => {
        const orderWithId = {
          ...order,
          id: order.pickingOrderId,
          plant: order.plant,
        };
        return this.container.items.upsert(orderWithId).catch((error) => {
          this.customLogger.error(
            `Failed to upsert order with ID ${orderWithId.id}:`,
            context,
            error,
          );
        });
      });

      // Wait for all upsert operations in the batch to complete
      await Promise.all(upsertPromises);
    } catch (error) {
      this.customLogger.error(
        `Error upserting shop orders into Cosmos DB: ${error}`,
        context,
        error.stack,
      );
      throw error; // Optionally rethrow the error for further handling
    }
  }

  public async deleteShopOrders(
    partitionKey: string,
    shopOrderIds: Array<PickingOrderList>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteShopOrders',
      plant: Number(partitionKey),
      service: 'CosmosDatabaseService',
    };
    try {
      const deletePromises = shopOrderIds.map(async (id) => {
        try {
          await this.container.item(id.pickingOrderId, id.plant).delete();
        } catch (error) {
          if (error.code === 404 || error.statusCode === 404) return;
          this.customLogger.error(
            `Plant ${partitionKey} Failed to delete order with ID ${id.pickingOrderId}: ${error}`,
            context,
            error.stack,
          );
          // Optionally implement retry logic or handle the error here
        }
      });

      // Wait for all delete operations to complete
      await Promise.all(deletePromises);
    } catch (error) {
      this.customLogger.error(
        ` Plant ${partitionKey} Error deleting shop orders from Cosmos DB: ${error}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async updateWithBatch(shopOrders: Array<ShopOrder>): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateWithBatch',
      plant: shopOrders[0]?.plant,
      service: 'CosmosDatabaseService',
    };

    try {
      // Convert Date fields to strings before upsertin
      // Prepare bulk upsert operations
      const upsertOperations: Array<ReplaceOperationInput> = shopOrders.map(
        (order) => {
          const orderWithId = {
            ...CosmosDatabaseService.serializeDates(order), // Convert all Date fields
            id: order.pickingOrderId, // Set shopOrder as the unique ID
          };

          return {
            id: order.pickingOrderId,
            ifMatch: order.etag,
            operationType: BulkOperationType.Replace,
            partitionKey: order.plant, // Ensure correct partitioning
            resourceBody: orderWithId,
          };
        },
      );

      // Perform bulk upsert
      const chunkSize = 100;

      // Step 1: Split upsertOperations into chunks
      const chunks = Array.from(
        { length: Math.ceil(upsertOperations.length / chunkSize) },
        (_, index) =>
          upsertOperations.slice(index * chunkSize, (index + 1) * chunkSize),
      );

      // Step 2: Process chunks using pMap
      await pMap(
        chunks,
        async (chunk) => {
          await this.container.items.bulk(chunk);
        },
        { concurrency: 1 }, // Or more if bulk operations can run in parallel
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting shop orders into Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async insertWithBatch(shopOrders: Array<ShopOrder>): Promise<void> {
    const context: JobsLogContext = {
      method: 'insertWithBatch',
      plant: shopOrders[0]?.plant,
      service: 'CosmosDatabaseService',
    };

    try {
      // Convert Date fields to strings before inserting

      // Prepare bulk insert operations
      const insertOperations: Array<CreateOperationInput> = shopOrders.map(
        (order) => {
          const orderWithId = {
            ...CosmosDatabaseService.serializeDates(order), // Convert all Date fields
            id: order.pickingOrderId, // Use shopOrder as the unique ID
          };

          return {
            id: order.pickingOrderId,
            operationType: BulkOperationType.Create, // Create operation for insert
            partitionKey: order.plant, // Ensure correct partitioning
            resourceBody: orderWithId,
          };
        },
      );

      // Perform bulk insert
      const chunkSize = 100;

      // Step 1: Break insertOperations into chunks
      const chunks = Array.from(
        { length: Math.ceil(insertOperations.length / chunkSize) },
        (_, index) =>
          insertOperations.slice(index * chunkSize, (index + 1) * chunkSize),
      );

      // Step 2: Process chunks with p-map
      await pMap(
        chunks,
        async (chunk) => {
          await this.container.items.bulk(chunk);
        },
        { concurrency: 1 }, // Adjust if parallelism is safe and desired
      );
    } catch (error) {
      this.customLogger.error(
        `Error inserting shop orders into Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async deleteIfExistsByIds(
    ids: Array<string>,
    partitionKey: number,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteIfExistsByIds',
      plant: partitionKey,
      service: 'CosmosDatabaseService',
    };

    try {
      if (ids.length === 0) {
        return;
      }

      const existingIds: Set<string> = new Set();
      const existenceChunkSize = 1000;

      // Step 1: Chunk the IDs for existence check
      const existenceChunks = Array.from(
        { length: Math.ceil(ids.length / existenceChunkSize) },
        (_, index) =>
          ids.slice(
            index * existenceChunkSize,
            (index + 1) * existenceChunkSize,
          ),
      );

      // Step 2: Use pMap to query existence in parallel (adjust concurrency as needed)
      await pMap(
        existenceChunks,
        async (chunk) => {
          const parameterNames = chunk.map((_, index) => `@id${index}`);
          const queryText = `SELECT c.id FROM c WHERE c.id IN (${parameterNames.join(',')})`;
          const parameters = chunk.map((id, index) => ({
            name: `@id${index}`,
            value: id,
          }));

          const query = {
            query: queryText,
            parameters,
          };

          const { resources } = await this.container.items
            .query(query, { partitionKey })
            .fetchAll();

          for (const document of resources) {
            existingIds.add(document.id);
          }
        },
        { concurrency: 1 }, // You can adjust this safely
      );

      if (existingIds.size === 0) {
        return;
      }

      // Step 3: Prepare delete operations from existing IDs
      const deleteOperations = ids
        .filter((id) => existingIds.has(id))
        .map((id) => ({
          id,
          operationType: BulkOperationType.Delete,
          partitionKey,
        }));

      const deleteChunkSize = 100;
      const deleteChunks = Array.from(
        { length: Math.ceil(deleteOperations.length / deleteChunkSize) },
        (_, index) =>
          deleteOperations.slice(
            index * deleteChunkSize,
            (index + 1) * deleteChunkSize,
          ),
      );

      // Step 4: Delete using pMap
      await pMap(
        deleteChunks,
        async (chunk) => {
          await this.container.items.bulk(chunk);

          // Add a 2-second delay after processing each chunk
          await new Promise<void>((resolve) => {
            setTimeout(() => {
              resolve();
            }, 1000);
          });
        },
        { concurrency: 1 }, // Increase if safe for your Cosmos setup
      );
    } catch (error) {
      this.customLogger.error(
        `Error during conditional deletion in Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getEtagsByIds(
    ids: Array<string>, // Array of IDs
    plant: number, // Plant number to filter by
  ): Promise<Record<string, string> | undefined> {
    // Return type as Record<string, string>
    const context: JobsLogContext = {
      method: 'getEtagsByIds',
      service: 'CosmosDatabaseService',
    };

    const result: Record<string, string> = {}; // Initialize as an object

    try {
      if (ids.length === 0) {
        return result; // Return an empty object if no IDs provided
      }

      // Prepare parameters for the query

      // Add the plant parameter

      const inClause = ids.map((id) => `'${id}'`).join(', ');

      // Cosmos DB query with the plant and IDs filter
      const querySpec = {
        query: `SELECT c.id, c._etag as etag  FROM c WHERE c.id IN (${inClause}) AND c.plant = ${plant}`,
      };
      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      // Populate result object with id and etag
      for (const item of resources) {
        result[item.id] = item.etag;
      }

      return result; // Return the record (object)
    } catch (error) {
      this.customLogger.error(
        `Error fetching etags by IDs for plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  public async replaceUpdatesByWksByBatch(
    plant: number,
    wksToBeUpdated: Record<string, OrderUpdate>,
  ): Promise<void> {
    const wkIds = Object.keys(wksToBeUpdated); // ✅ dynamically get all WKS IDs
    await pMap(
      wkIds,
      async (id) => {
        const updates = wksToBeUpdated[id]?.updates ?? {};
        const { resource: existingDocument } = await this.container
          .item(id, plant)
          .read();
        if (existingDocument) {
          const patchOperations: Array<PatchOperation> = Object.entries(
            updates,
          ).map(
            ([key, value]) =>
              ({
                op: 'set',
                path: `/${key}`,
                value,
              }) as PatchOperation,
          );
          try {
            await this.container.item(id, plant).patch(patchOperations);
            // Optional: log successful update
          } catch (error) {
            if (error.code === 404) {
              this.customLogger.warn(
                `wk ${id} not found, skipping`,
                error.message,
              );
            } else {
              this.customLogger.error(
                `error in patching wk ${id}, skipping`,
                error.message,
              );
            }
          }
        }
      },
      { concurrency: 5 }, // Parallel patching
    );
  }
}

