/**
 * Adds work center resource details to the order.
 * @param order - The original shop order.
 * @param resourceDetail - The work center details to be added.
 * @returns The updated shop order with resource details.
 */
export function addResourceDetail(
  order: ShopOrder,
  resourceDetail: WorkcenterResponseDTO | undefined,
): ShopOrder {
  const updatedOrder = { ...order };
  if (resourceDetail && resourceDetail?.advancePickingDuration !== undefined) {
    updatedOrder.advancePickingDuration = resourceDetail.advancePickingDuration;
    updatedOrder.workcenterDescription = resourceDetail.description;
  } else {
    updatedOrder.advancePickingDuration = '';
    updatedOrder.workcenterDescription = '';
  }
  return updatedOrder;
}

/**
 * Adds the customer description to the order if available.
 * @param order - The shop order to update.
 * @param customerDesc - A record of customer descriptions indexed by shop order number.
 * @returns ShopOrder
 */
export function addCustomerDesc(
  order: ShopOrder,
  customerDesc: Record<string, string> | undefined,
): ShopOrder {
  const updatedOrder = { ...order };
  updatedOrder.customerDesc =
    (order.customer && customerDesc?.[order.customer]) ?? '';
  return updatedOrder;
}

/**
 * Extracts unique values from a list or record of picking orders.
 * @param pickingOrders - Array or record of picking orders to analyze.
 * @returns An object containing arrays of unique values for customers, materials, locations, etc.
 */
export function extractUniqueValues(
  pickingOrders: Record<string, PickingOrderList> | Array<PickingOrderList>,
): {
  customers: Array<string>;
  materialIds: Array<string>;
  locations: Array<string>;
  relatedOrders: Array<string>;
  pickingOrderIds: Array<string>;
  workcenters: Array<string>;
} {
  const customers = new Set<string>();
  const materialIds = new Set<string>();
  const locations = new Set<string>();
  const relatedOrders = new Set<string>();
  const workcenters = new Set<string>();
  const pickingOrderIds = new Set<string>();

  for (const order of Object.values(pickingOrders)) {
    if (order.customer) customers.add(order.customer);
    if (order.workcenter) workcenters.add(order.workcenter);
    if (order.material) materialIds.add(order.material);
    if (order.sourceLocation) locations.add(order.sourceLocation);
    if (order.destinationLocation) locations.add(order.destinationLocation);
    if (order.relatedOrder) relatedOrders.add(order.relatedOrder);
    if (order.pickingOrderId) pickingOrderIds.add(order.pickingOrderId);
  }

  return {
    customers: [...customers],
    locations: [...locations],
    materialIds: [...materialIds],
    pickingOrderIds: [...pickingOrderIds],
    relatedOrders: [...relatedOrders],
    workcenters: [...workcenters],
  };
}

