import { Mutex } from 'async-mutex';

export const pendingMessageStats = {
  count: 0,
};

export const pendingMessageCountMutex = new Mutex();

/**
 * Increment the general counter
 */
export function incrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count += 1;
  });
}

/**
 * Decrement the general counter
 */
export function decrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count -= 1;
  });
}

/**
 * Return count property from pendingMessageStats
 * @returns count property
 */
export function getPendingMessagesCount(): number {
  return pendingMessageStats.count;
}

import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { PickingOrderList } from '@/interface/picking-order-list';
import { ShopOrder } from '@/interface/shop-order';
import { UpdateCacheOrders } from '@/update-cache/update-cache-orders';

// Create a function to process cache updates sequentially for a given order
/**
 *
 * @param pickingOrder - The picking order to be processed.
 * @param updateCacheServices - Update cache services
 * @param updateCacheServices.updateCacheOrders - A function that updates the cache for orders.
 *     This function should accept a PickingOrderRequestDto object and return a promise
 *     that resolves to a ShopOrder.
 * @param logger logger to log information
 * @param shopOrderResultsBuffer - the array that contain the result
 * @returns shopOrder results
 */
export async function createUpdateOrder(
  pickingOrder: PickingOrderList,
  updateCacheServices: {
    updateCacheOrders: UpdateCacheOrders;
  },
  logger: AppLogger,
  shopOrderResultsBuffer: Array<ShopOrder>,
): Promise<void> {
  try {
    const { updateCacheOrders } = updateCacheServices;
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheSequentially - processItem',
    };
    // Step 1: Update Cache for Order
    logOperationInfo.name = 'updateCacheForOrder';
    const updatedShopOrder = (await execAndLog(
      logger,
      () => updateCacheOrders.updateCacheForOrder(pickingOrder),
      logOperationInfo,
      { item: pickingOrder },
    )) as ShopOrder;

    if (!updatedShopOrder) {
      return; // Skip further processing if order cache update fails
    }
    // Add the updated ShopOrder to the results buffer
    shopOrderResultsBuffer.push(updatedShopOrder);
  } catch (error) {
    logger.error(
      `Failed to process cache updates for order: ${pickingOrder.pickingOrderId}`,
      error,
    );
  }
}

