import { UpdateCacheOrders } from '@/update-cache/update-cache-orders';
import { UpdateCacheHYR } from '@/update-cache/update-cache-plant-hierarchy';
import { UpdateCacheSequentially } from '@/update-cache/update-cache-sequentially';
import { UpdateCacheShipment } from '@/update-cache/update-cache-shipment';
import { UpdateCacheTransfer } from '@/update-cache/update-cache-transfer';

// Function to instantiate UpdateCacheSequentially and its dependencies
/**
 * @param daprClient - The Dapr client instance
 * @returns instance of UpdateCacheSequentially
 */
export async function instantiateUpdateCacheSequentially(
  daprClient: DaprClient,
): Promise<UpdateCacheSequentially> {
  // Instantiate the core services
  const configService = new ConfigService();
  const appConfigIntialConfigService = new AppConfigInitialConfigService(
    configService,
  );
  const appConfig = new AppConfigService(appConfigIntialConfigService);
  const loggerConfigService = new LoggerConfigService(configService, appConfig);
  const appLogger = new AppLogger(loggerConfigService);
  const daprConfigService = new DaprConfigService(configService, appLogger);
  const cosmosDatabaseConfigService = new CosmosDatabaseConfigService(
    configService,
    appLogger,
  );
  const cosmosDatabseService = new CosmosDatabaseService(
    cosmosDatabaseConfigService,
    appLogger,
  );
  // Instantiate the API services
  const orderApi = new OrderApi(daprClient, daprConfigService, appLogger);
  const productionApi = new ProductionApi(
    daprClient,
    daprConfigService,
    appLogger,
  );
  const masterApi = new MasterApi(daprClient, daprConfigService, appLogger);
  const shipmentApi = new ShipmentApi(daprClient, daprConfigService, appLogger);
  const plantHyrApi = new PlantHierarchyApi(
    daprClient,
    daprConfigService,
    appLogger,
  );
  const transferApi = new TransferApi(daprClient, daprConfigService, appLogger);

  // Instantiate the individual cache updaters
  const updateCacheOrders = new UpdateCacheOrders(orderApi, appLogger);
  const updateCacheContainers = new UpdateCacheContainers(
    productionApi,
    appLogger,
  );
  const updateCacheMasters = new UpdateCacheMaster(masterApi, appLogger);
  const updateCacheShipment = new UpdateCacheShipment(
    shipmentApi,
    plantHyrApi,
    appLogger,
  );
  const updateCacheHYR = new UpdateCacheHYR(plantHyrApi, appLogger);
  const updateCacheTransfer = new UpdateCacheTransfer(transferApi, appLogger);
  const sharedCacheUpdateService = new SharedCacheUpdateService(
    updateCacheContainers,
    updateCacheMasters,
    updateCacheShipment,
    updateCacheHYR,
    updateCacheTransfer,
  );

  // Instantiate and return the UpdateCacheSequentially with all its dependencies
  return new UpdateCacheSequentially(
    updateCacheOrders,
    sharedCacheUpdateService,
    cosmosDatabseService,
    appLogger,
  );
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

/**
 * DaprClientProvider - Provides and manages a singleton DaprClient instance
 *
 * This provider:
 * - Creates a single DaprClient instance when the module initializes
 * - Manages the client's lifecycle (initialization and cleanup)
 * - Implements proper disposal to prevent memory leaks
 * - Provides configuration from DaprConfigService
 *
 * The provider acts as a factory that returns the same DaprClient instance
 * to all consumers, ensuring a true singleton pattern.
 */
@Injectable()
export class DaprClientProvider
  extends DaprClient
  implements OnModuleInit, OnModuleDestroy
{
  private isInitialized = false;

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    // Initialize the DaprClient with default configuration
    // The DaprClient will use environment variables or default values
    super();
  }

  /**
   * Called when the module is initialized
   * Ensures the DaprClient is ready for use
   */
  public async onModuleInit(): Promise<void> {
    const context: JobsLogContext = {
      service: 'DaprClientProvider',
      method: 'onModuleInit',
    };

    try {
      this.customLogger.log('DaprClient initializing...', context);

      // The DaprClient doesn't require explicit initialization in most cases,
      // But you can add connection checks or health checks here if needed

      this.isInitialized = true;
      this.customLogger.log('DaprClient initialized successfully', context);
    } catch (error) {
      this.customLogger.error(
        'Failed to initialize DaprClient',
        context,
        error,
      );
      throw error;
    }
  }

  /**
   * Called when the module is destroyed
   * Ensures proper cleanup of resources
   */
  public async onModuleDestroy(): Promise<void> {
    const context: JobsLogContext = {
      service: 'DaprClientProvider',
      method: 'onModuleDestroy',
    };

    try {
      if (this.isInitialized) {
        this.customLogger.log('DaprClient shutting down...', context);

        // Perform any necessary cleanup
        // Note: DaprClient doesn't have a built-in dispose method,
        // But you can add cleanup logic here if needed

        this.isInitialized = false;
        this.customLogger.log('DaprClient shut down successfully', context);
      }
    } catch (error) {
      this.customLogger.error(
        'Error during DaprClient shutdown',
        context,
        error,
      );
    }
  }

  /**
   * Check if the client is initialized and ready to use
   * @returns True if the client is initialized and ready, false otherwise
   */
  public isReady(): boolean {
    return this.isInitialized;
  }
}

