#!/usr/bin/env node
import {
  CosmosClient,
  BulkOperationType,
  OperationResponse,
  Container,
  CreateOperationInput,
} from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { Logger } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

const logger = new Logger('SyncCosmos');

/**
 * Sleep helper to avoid promise executor return issues
 * @param ms // Milliseconds to sleep
 */
function sleep(ms: number): Promise<void> {
  return new Promise<void>((resolve) => {
    setTimeout(() => resolve(), ms);
  });
}

/**
 * Perform safe bulk insert with 429 retry/backoff
 * @param targetContainer The Cosmos container to insert documents into
 * @param operations Array of bulk operations to perform
 * @param maxRetries Maximum number of retry attempts in case of throttling (default 5)
 * @returns The total number of documents successfully inserted
 */
async function safeBulkInsert(
  targetContainer: Container,
  operations: Array<CreateOperationInput>,
  maxRetries = 5,
): Promise<number> {
  let totalInserted = 0;
  let remainingOps = [...operations];
  let attempt = 0;

  while (remainingOps.length > 0 && attempt < maxRetries) {
    const results: Array<OperationResponse> =
      await targetContainer.items.bulk(remainingOps);
    const failedOps: Array<CreateOperationInput> = [];

    for (const [index, response] of results.entries()) {
      const op = remainingOps[index];

      switch (response.statusCode) {
        case 201: {
          totalInserted += 1;
          break;
        }
        case 409: {
          break;
        }
        case 429: {
          failedOps.push(op);
          break;
        }
        default: {
          logger.error(
            `Failed to insert document ${JSON.stringify(op, undefined, 2)}: ${response.statusCode}`,
          );
        }
      }
    }

    remainingOps = failedOps;
    if (remainingOps.length > 0) {
      const delay = 2 ** attempt * 50;
      logger.warn(
        `⚠️ Throttled. Retrying ${remainingOps.length} items after ${delay}ms...`,
      );
      await sleep(delay);
    }
    attempt = +1;
  }

  if (remainingOps.length > 0) {
    logger.error(
      `❌ Could not insert ${remainingOps.length} items after ${maxRetries} retries`,
    );
  }

  return totalInserted;
}

/**
 * Main migration bootstrap
 */
async function bootstrap(): Promise<void> {
  const appContext = await NestFactory.createApplicationContext(AppModule);

  try {
    const credential = new DefaultAzureCredential();

    const sourceEndpoint = process.env.SOURCE_COSMOS_DB_ENDPOINT;
    const targetEndpoint = process.env.TARGET_COSMOS_DB_ENDPOINT;
    const databaseName = 'Mes';
    const containerName = process.env.COSMOS_DB_CONTAINER;

    if (!sourceEndpoint || !targetEndpoint || !databaseName || !containerName) {
      throw new Error('Missing required Cosmos environment variables');
    }

    const sourceClient = new CosmosClient({
      aadCredentials: credential,
      endpoint: sourceEndpoint,
    });
    const targetClient = new CosmosClient({
      aadCredentials: credential,
      endpoint: targetEndpoint,
    });

    const sourceContainer = sourceClient
      .database(databaseName)
      .container(containerName);
    const targetContainer = targetClient
      .database(databaseName)
      .container(containerName);

    logger.log('🚀 Starting batched migration...');

    // Clear target container first
    const readBatchSize = 2000;
    const writeBatchSize = 80;
    let continuationToken: string | undefined;
    let totalInserted = 0;

    do {
      const { resources: documents, continuationToken: newToken } =
        await sourceContainer.items
          .query('SELECT * FROM c', {
            maxItemCount: readBatchSize,
            continuationToken,
          })
          .fetchNext();

      continuationToken = newToken;
      if (!documents?.length) break;

      logger.log(`📦 Read batch of ${documents.length} documents...`);

      for (let index = 0; index < documents.length; index += writeBatchSize) {
        const chunk = documents.slice(index, index + writeBatchSize);

        const operations = chunk.map((item) => ({
          id: item.id,
          operationType: BulkOperationType.Create,
          resourceBody: item,
        }));

        const inserted = await safeBulkInsert(targetContainer, operations);
        totalInserted += inserted;

        logger.log(
          `✅ Wrote ${chunk.length} docs, total inserted so far: ${totalInserted}`,
        );
      }
    } while (continuationToken);

    logger.log(
      `🎯 Migration finished. Total new documents inserted: ${totalInserted}`,
    );
  } catch (error) {
    logger.error(
      `❌ Error during batched Cosmos migration: ${error instanceof Error ? error.message : error}`,
      error instanceof Error ? error.stack : undefined,
    );
  } finally {
    await appContext.close();
    process.exit(0);
  }
}

bootstrap();

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-store.service';
import { LastUpdateTaskRecord } from '@/interface/last-update-task-record';

@Injectable()
export class LastUpdateTaskRecordService {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async readLastUpdateTaskRecord(
    plantKey: string,
  ): Promise<LastUpdateTaskRecord> {
    const { redisUpdateAmr } = this.redisConfigService;
    const context: JobsLogContext = {
      method: 'readLastUpdateTaskRecord',
      plant: Number(plantKey),
      service: 'LastUpdateTaskRecordService',
    };
    try {
      const result: unknown = await this.daprClient.state.get(
        redisUpdateAmr,
        plantKey,
      );
      let lastUpdateResult: LastUpdateTaskRecord = {
        lastUpdateTime: new Date(),
        updatedOn: new Date(),
      };
      if (result !== undefined && result !== '') {
        // Attempt to parse the result if it's a string
        lastUpdateResult =
          typeof result === 'string'
            ? (JSON.parse(result) as LastUpdateTaskRecord)
            : (result as LastUpdateTaskRecord);
      }

      lastUpdateResult.lastUpdateTime = new Date(
        lastUpdateResult.lastUpdateTime,
      );

      lastUpdateResult.updatedOn = new Date(lastUpdateResult.updatedOn);
      return lastUpdateResult;
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantKey} - Error reading from Redis: ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Rethrow the error after logging
    }
  }

  public async writeLastUpdateTaskRecord(
    plantKey: string,
    lastUpdateTaskRecord: LastUpdateTaskRecord,
  ): Promise<void> {
    const { redisUpdateAmr } = this.redisConfigService;
    const context: JobsLogContext = {
      method: 'writeLastUpdateTaskRecord',
      plant: Number(plantKey),
      service: 'LastUpdateTaskRecordService',
    };
    try {
      const value = { ...lastUpdateTaskRecord };
      value.updatedOn = new Date();
      // In migration → write to both old and new stores

      await this.daprClient.state.save(redisUpdateAmr, [
        { key: plantKey, value },
      ]);
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantKey} writeRecords - Error writing to Redis ${plantKey} ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Rethrow the error after loggingObject:
    }
  }
}

import { Injectable } from '@nestjs/common';
import { UpdateCacheContainers } from './update-cache-containers';
import { UpdateCacheMaster } from './update-cache-master';
import { UpdateCacheHYR } from './update-cache-plant-hierarchy';
import { UpdateCacheShipment } from './update-cache-shipment';
import { UpdateCacheTransfer } from './update-cache-transfer';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class SharedCacheUpdateService {
  private static async executeWithOptionalLog(
    name: string,
    operation: () => Promise<Array<ShopOrder>>,
    logFunction?: (
      name: string,
      operation: () => Promise<Array<ShopOrder>>,
    ) => Promise<Array<ShopOrder>>,
  ): Promise<Array<ShopOrder>> {
    return logFunction ? logFunction(name, operation) : operation();
  }

  public constructor(
    private readonly updateCacheContainers: UpdateCacheContainers,
    private readonly updateCacheMasters: UpdateCacheMaster,
    private readonly updateCacheShipment: UpdateCacheShipment,
    private readonly updateCacheHYR: UpdateCacheHYR,
    private readonly updateCacheTransfer: UpdateCacheTransfer,
  ) {}

  public async updateAllCaches(
    plant: string,
    orders: Array<ShopOrder>,
    logFunction?: (
      name: string,
      operation: () => Promise<Array<ShopOrder>>,
    ) => Promise<Array<ShopOrder>>,
  ): Promise<Array<ShopOrder>> {
    const updateSteps: Array<{
      name: string;
      fn: (
        plant: string,
        orders: Array<ShopOrder>,
      ) => Promise<Array<ShopOrder>>;
    }> = [
      {
        name: 'updateCacheShipment',
        fn: this.updateCacheShipment.updateCacheShipment.bind(
          this.updateCacheShipment,
        ),
      },
      {
        name: 'updateCacheMaster',
        fn: this.updateCacheMasters.updateCacheMaster.bind(
          this.updateCacheMasters,
        ),
      },
      {
        name: 'updateCachePlantHYR',
        fn: this.updateCacheHYR.updateCachePlantHYR.bind(this.updateCacheHYR),
      },
      {
        name: 'updateCacheContainer',
        fn: this.updateCacheContainers.updateCacheContainer.bind(
          this.updateCacheContainers,
        ),
      },
      {
        name: 'updateCacheTransfer',
        fn: this.updateCacheTransfer.updateCacheTransfer.bind(
          this.updateCacheTransfer,
        ),
      },
    ];
    let updateOrders: Array<ShopOrder> = orders;
    for (const step of updateSteps) {
      updateOrders = await SharedCacheUpdateService.executeWithOptionalLog(
        step.name,
        () => step.fn(plant, orders),
        logFunction,
      );
    }

    return updateOrders;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { ProductionApi } from 'src/api/production-api';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { ContainerByIdResponseDto } from '@/dtos/container-by-id-response.dto';
import { ShopOrder } from '@/interface/shop-order';

/**
 * Initializes the label order list by categorizing shop orders into multiple and single label orders.
 * @param shopOrders - An array of shop orders to be categorized.
 * @returns An object containing two arrays: multipleLabelOrders and singleLabelOrders.
 */
function initLabelOrderList(shopOrders: Array<ShopOrder>): {
  singleLabelOrders: Array<string>;
} {
  const singleLabelOrders: Array<string> = [];

  for (const shoporder of shopOrders) {
    if (
      shoporder.relatedLabel !== 'NULL' &&
      shoporder.relatedLabel !== 'MULTIPLE'
    ) {
      singleLabelOrders.push(String(shoporder.relatedLabel));
    }
  }

  return { singleLabelOrders };
}

@Injectable()
export class UpdateCacheContainers {
  public constructor(
    private readonly productionApi: ProductionApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheContainer(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'updateCacheContainer',
      plant: Number(plant),
      service: 'UpdateCacheContainers',
    };

    // Extract only singleLabelOrders, skip MULTIPLE logic
    const { singleLabelOrders } = initLabelOrderList(shopOrders);

    try {
      // Skip MULTIPLE call
      const containerDataforSingleLabel =
        await this._getContainerDataforSingleLabel(plant, singleLabelOrders);

      for (const shopOrder of shopOrders) {
        if (shopOrder.relatedLabel === 'MULTIPLE') {
          // Reset values but do not assign from API
          shopOrder.createOn = '';
          shopOrder.containerNumber = '';
          shopOrder.realProductionTime = '';
        } else {
          const container = containerDataforSingleLabel[shopOrder.relatedLabel];
          if (container) {
            shopOrder.createOn = container.createOn;
            shopOrder.huCurrentStorageLocation =
              container.currentStorageLocation;
            shopOrder.realProductionTime = container.bookDate ?? '';
          }
        }
      }
      const newShopOrders = shopOrders;
      return newShopOrders;
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} - Error updateCacheContainer: ${error.message}`,
        context,
        error.stack,
      );
      return shopOrders;
    }
  }

  private async _getContainerDataforSingleLabel(
    plant: string,
    singleLabelOrders: Array<string>,
  ): Promise<Record<string, ContainerByIdResponseDto>> {
    const logOperationInfo = {
      name: 'fetchContainerByContainerIdList',
      srcLocation: 'updateCacheContainer',
    };

    let containerDataforSingleLabel: Record<string, ContainerByIdResponseDto> =
      {};

    if (singleLabelOrders.length > 0) {
      containerDataforSingleLabel = await execAndLog(
        this.customLogger,
        () =>
          this.productionApi.fetchContainerByContainerIdList(
            plant,
            singleLabelOrders,
          ),
        logOperationInfo,
        { singleLabelOrders },
      );
    }
    return containerDataforSingleLabel;
  }
}

