import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OrderApi } from 'src/api/order-api';
import { MinSeqNumberRequestDto } from 'src/dtos/min-seq-number-request.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { MaterialRequestDto } from '@/dtos/material-request.dto';
import { PickingOrderList } from '@/interface/picking-order-list';

@Injectable()
export class UpdateCacheOrders {
  public constructor(
    private readonly orderapi: OrderApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheForOrder(
    receivedData: PickingOrderList,
  ): Promise<object | undefined> {
    const context: JobsLogContext = {
      method: 'updateCacheMaster',
      plant: Number(receivedData.plant),
      service: 'updateCacheMaster',
    };
    try {
      // Fetch picking order data from the API
      // Extract data from pickingData
      const {
        pickingOrderId,
        plant,
        material,
        workcenter,
        customStatus,
        pikNumber,
        sourceLocation,
        dateTransfer,
        destinationLocation,
        endProductionTime,
        huCurrentStorageLocation,
        alertCreated,
        outbound,
        tpaNumber,
        relatedOrder,
        containerNumber,
        plannedCompDate,
        plannedStartDate,
        customer,
        status,
        relatedLabel,
        scheduledCompDate,
        reschedulerWkHistories,
        alertId,
        alertStatus,
        alertCreationTime,
        newPromiseTime,
        sfgWorkcenter,
        alertLevel,
      } = receivedData;
      // Fetch sebango from material-dtl in order domain
      const materialRequest = new MaterialRequestDto();
      materialRequest.plant = receivedData.plant;
      materialRequest.materialId = receivedData.material; // Using the receivedData instead of fetching from Redis

      const materialResponse =
        await this.orderapi.fetchSebango(materialRequest);
      const sebango = materialResponse?.sebango ?? '';

      const plantConfig = await this.orderapi.fetchPlantConfigOrder(plant);

      const { toleranceValueWk } = plantConfig;

      // Build the updated pickingOrderData
      const pickingOrderData = {
        alertCreated,
        alertCreationTime,
        alertId,
        alertLevel,
        alertStatus,
        closeable: false,
        color: '',
        containerNumber,
        customStatus,
        customer,
        dateTransfer,
        departureTime: plannedCompDate,
        destinationLocation,
        endProdColor: '',
        endProdTimeType: '',
        endProductionTime,
        huCurrentStorageLocation,
        lockAction: '',
        lockDateTime: '',
        lockList: [],
        material,
        newPromiseTime,
        outbound,
        overdue: false,
        pickingOrderId,
        pickingTime: plannedStartDate,
        pickingTimeType: '',
        pikNumber,
        plant,
        realProductionTime: '',
        relatedLabel,
        reschedulerWkHistories,
        scheduledCompDate,
        sebango,
        sfgWorkcenter,
        sourceLocation,
        status,
        toleranceValueWk,
        tpaCode: tpaNumber,
        tpaNumber,
        workcenter,
        workcenterDescription: '',
      };
      // If a related order exists, fetch the minimum sequence number
      let seqnumValue = '';
      if (relatedOrder) {
        const minSeqNumberRequestDto = new MinSeqNumberRequestDto();
        minSeqNumberRequestDto.plant = receivedData.plant;
        minSeqNumberRequestDto.relatedOrder = relatedOrder;
        const minSeqNumberResponse = await this.orderapi.fetchMinSeqNum(
          minSeqNumberRequestDto,
        );
        if (minSeqNumberResponse?.minSeqNum) {
          seqnumValue = minSeqNumberResponse.minSeqNum;
        }
      }

      // Validate the consistency of received data with API data
      if (!pickingOrderId.includes(receivedData.pickingOrderId)) {
        return undefined;
      }
      if (Number(plant) !== Number(receivedData.plant)) {
        return undefined;
      }

      // Update the pickingOrderData with the sequence number
      const updatedData = {
        ...pickingOrderData,
        seqnum: seqnumValue,
      };

      // Handle lockAction reset based on certain conditions
      if (
        pickingOrderData.lockAction === 'NOT_AVAILABLE' ||
        pickingOrderData.lockAction === 'RESCH' ||
        receivedData.plannedStartDate !== plannedStartDate
      ) {
        updatedData.lockAction = '';
        updatedData.lockDateTime = '';
        updatedData.lockList = [];
      }
      // Return the updated pickingOrderData
      return updatedData;
    } catch (error) {
      this.customLogger.error(
        `Plant ${receivedData.plant} - Error updateCacheForOrder: ${error.message}`,
        context,
        error.stack,
      );
      return undefined; // Return undefined in case of an error
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { PlantHierarchyApi } from 'src/api/plant-hierarchy-api';
import { AppLogger } from '@/common/logger/app-logger';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheHYR {
  public constructor(
    private readonly plantHiearchy: PlantHierarchyApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCachePlantHYR(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'updateCachePlantHYR',
      plant: Number(plant),
      service: 'UpdateCacheHYR',
    };
    try {
      const uniqueWorkcenterIds = [
        ...new Set(
          shopOrders
            .map((item) => item.workcenter)
            .filter((id): id is string => !!id),
        ),
      ];

      const responseInvoker =
        await this.plantHiearchy.fetchWorkcenterDetailsByLisId(
          plant,
          uniqueWorkcenterIds,
        );

      if (responseInvoker) {
        for (const shoporder of shopOrders) {
          shoporder.workcenterDescription =
            responseInvoker[shoporder.workcenter].description;
          shoporder.advancePickingDuration =
            responseInvoker[shoporder.workcenter].advancePickingDuration;
          shoporder.overdue = this.getOverdueAttribute(
            shoporder.pickingTime,
            responseInvoker[shoporder.workcenter].advancePickingDuration,
          );
        }
        return shopOrders;
      }
      return shopOrders; // Return undefined if the workcenter details are not fetched successfully
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} - Error updateCachePlantHYR: ${error.message}`,
        context,
        error.stack,
      );
      return shopOrders; // Return undefined in case of an error
    }
  }

  public getOverdueAttribute(
    plannedStartDate: string,
    duration: string,
  ): boolean {
    const context: JobsLogContext = {
      method: 'updateOverdueAttribute',
      service: 'UpdateCacheHYR',
    };
    try {
      const now = Date.now();
      const advanceDuration = typeof duration === 'number' ? duration : 0;
      const plannedStart = new Date(plannedStartDate).getTime();
      const adjustedStart = plannedStart + advanceDuration * 60_000; // Convert minutes to milliseconds
      const overdue = adjustedStart < now;
      return overdue;
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error.message}`,
        context,
        error.stack,
      );
      // This.logger.error(error.stack);
      throw new Error('Error processing UpdateOverdueAttribute');
    }
  }

  public async updateColorAttribute(
    date: string,
    duration: string,
  ): Promise<string> {
    const context: JobsLogContext = {
      method: 'updateColorAttribute',
      service: 'UpdateCacheHYR',
    };
    try {
      const currentDate = Date.now();
      const convertedDate = new Date(date).getTime();
      const differenceInMinutes = Math.floor(
        (currentDate - convertedDate) / (1000 * 60),
      );
      if (differenceInMinutes > 0) {
        return 'RED';
      }

      const advanceDuration = typeof duration === 'number' ? duration : 0;
      const adjustedStartDate = convertedDate + advanceDuration * 60_000;
      if (currentDate < adjustedStartDate) {
        return 'GREY';
      }
      return 'WHITE';
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error.message}`,
        context,
        error.stack,
      );
      // This.logger.error(error.stack);
      throw new Error('Error processing UpdateColorAttribute');
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { SharedCacheUpdateService } from './shared-cache-update.service';
import { UpdateCacheOrders } from './update-cache-orders';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseService } from '@/cosmos-db/cosmos.database.service';
import { createUpdateOrder } from '@/helpers/updates/create-update-order';
import { OrderUpdate } from '@/interface/order-update';
import { PickingOrderList, PickingOrder } from '@/interface/picking-order-list';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheSequentially {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly updateCacheOrders: UpdateCacheOrders,
    private readonly sharedCacheUpdateService: SharedCacheUpdateService,
    private readonly cosmosDabaseService: CosmosDatabaseService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  private async processPickingOrder(
    pickingOrder: PickingOrder,
    shopOrderResultsBuffer: Array<ShopOrder>,
    shopOrderToBeDeleted: Array<PickingOrderList>,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'updateCacheSequentially - processItem',
    };
    const context: JobsLogContext = {
      method: 'processPickingOrder',
      plant: pickingOrder.plant,
      service: 'UpdateCacheSequentially',
    };
    try {
      // Handle different statuses
      switch (pickingOrder.status) {
        case '501':
        case '502': {
          if (
            pickingOrder.customStatus !== undefined &&
            pickingOrder.customStatus !== ''
          ) {
            logOperationInfo.name = 'createUpdateOrder';
            // Continue processing with additional updates
            await execAndLog(
              this.customLogger,
              () =>
                createUpdateOrder(
                  pickingOrder,
                  {
                    updateCacheOrders: this.updateCacheOrders,
                  },
                  this.customLogger,
                  shopOrderResultsBuffer,
                ),
              logOperationInfo,
              { pickingOrder, shopOrderResultsBuffer },
            );
          }
          break;
        }
        case '503':
        case '504': {
          // Directly delete the order from cache if status is 504
          logOperationInfo.name = 'deleteFromCacheForOrder';
          shopOrderToBeDeleted.push(pickingOrder);
          break;
        }
        default: {
          this.customLogger.error(
            `Invalid status code: ${pickingOrder.pickingOrderId}`,
            context,
          );
        }
      }
    } catch (error) {
      this.customLogger.error(
        `Plant ${pickingOrder.plant} - Failed to process order ${pickingOrder.pickingOrderId}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async syncShopOrderResultsBuffer(
    plantId: number,
    shopOrderResultsBuffer: Array<ShopOrder>,
  ): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'syncShopOrderResultsBuffer',
    };
    const context: JobsLogContext = {
      method: 'syncShopOrderResultsBuffer',
      plant: plantId,
      service: 'UpdateCacheSequentially',
    };

    try {
      const plant = plantId.toString();
      const operationDetails = {
        plant,
        shopOrderResultsLength: shopOrderResultsBuffer.length,
      };

      const logFunction = (
        name: string,
        operation: () => Promise<Array<ShopOrder>>,
      ): Promise<Array<ShopOrder>> =>
        execAndLog(
          this.customLogger,
          operation,
          { ...logOperationInfo, name },
          operationDetails,
        );

      // ✨ One call replaces all individual execAndLog wrappers
      const updatedOrders = await this.sharedCacheUpdateService.updateAllCaches(
        plant,
        shopOrderResultsBuffer,
        logFunction,
      );

      // Log and save to Cosmos
      await execAndLog(
        this.customLogger,
        () => this.saveToCosmos(updatedOrders, plant),
        { ...logOperationInfo, name: 'saveToCosmos' },
        operationDetails,
      );

      shopOrderResultsBuffer.splice(0, shopOrderResultsBuffer.length); // Clear the array
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantId} failed to save shopOrderResultsBuffer in Cosmos ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  private async deleteShopOrderResultsBufferInCosmos(
    plantId: number,
    shopOrderToBeDeleted: Array<PickingOrderList>,
  ): Promise<void> {
    const logOperationInfo = {
      name: 'deleteShopOrderResultsBufferInCosmos',
      srcLocation: 'deleteShopOrderResultsBufferInCosmos',
    };
    const context: JobsLogContext = {
      method: 'deleteShopOrderResultsBufferInCosmos',
      plant: plantId,
      service: 'UpdateCacheSequentially',
    };
    try {
      const plant = plantId.toString();
      // Delete from cosmos DB
      await execAndLog(
        this.customLogger,
        () =>
          this.cosmosDabaseService.deleteShopOrders(
            plant,
            shopOrderToBeDeleted,
          ),
        logOperationInfo,
        { plant, shopOrderToBeDeletedLength: shopOrderToBeDeleted.length },
      );
      shopOrderToBeDeleted.splice(0, shopOrderToBeDeleted.length);
    } catch (error) {
      this.customLogger.error(
        `Plant ${plantId} failed to delete  shopOrderToBeDeleted in Cosmos ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async updateCacheSequentially(
    pickingOrders: Array<PickingOrderList>,
  ): Promise<void> {
    const shopOrderResultsBuffer: Array<ShopOrder> = []; // Array to hold results
    const shopOrderToBeDeleted: Array<PickingOrderList> = [];

    for (const pickingOrder of pickingOrders) {
      await this.processPickingOrder(
        pickingOrder,
        shopOrderResultsBuffer,
        shopOrderToBeDeleted,
      );

      // Check if we need to save to cosmos
      if (shopOrderResultsBuffer.length >= 200) {
        await this.syncShopOrderResultsBuffer(
          pickingOrder.plant,
          shopOrderResultsBuffer,
        );
      }

      if (shopOrderToBeDeleted.length >= 200) {
        await this.deleteShopOrderResultsBufferInCosmos(
          pickingOrder.plant,
          shopOrderToBeDeleted,
        );
      }
    }

    // Check if there are results to save at the end of processing
    if (shopOrderResultsBuffer.length > 0) {
      await this.syncShopOrderResultsBuffer(
        pickingOrders[0].plant,
        shopOrderResultsBuffer,
      );
    }

    if (shopOrderToBeDeleted.length > 0) {
      await this.deleteShopOrderResultsBufferInCosmos(
        pickingOrders[0].plant,
        shopOrderToBeDeleted,
      );
    }
  }

  private async saveToCosmos(
    shopOrderResults: Array<ShopOrder>,
    plantKey: string,
  ): Promise<void> {
    const logOperationInfo = {
      name: 'Upsert in cosmos',
      srcLocation: 'saveToCosmos',
    };
    const context: JobsLogContext = {
      method: 'saveToCosmos',
      plant: Number(plantKey),
      service: 'UpdateCacheSequentially',
    };
    try {
      await execAndLog(
        this.customLogger,
        () =>
          this.cosmosDabaseService.upsertBatchShopOrders(
            plantKey,
            shopOrderResults,
          ),
        logOperationInfo,
        { plant: plantKey, shopOrderResultsLength: shopOrderResults.length },
      );
    } catch (error) {
      this.customLogger.error(
        `plant ${plantKey} - Failed to save ShopOrders to Cosmos: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  public async replaceUpdateTocosmos(
    wksToBeUpdated: Record<string, OrderUpdate>,
    plantKey: number,
  ): Promise<void> {
    const logOperationInfo = {
      name: 'replace updated in cosmos',
      srcLocation: 'replaceUpdatesByWksByBatch',
    };
    const context: JobsLogContext = {
      method: 'replaceUpdatesByWksByBatch',
      plant: Number(plantKey),
      service: 'UpdateCacheSequentially',
    };
    try {
      await execAndLog(
        this.customLogger,
        () =>
          this.cosmosDabaseService.replaceUpdatesByWksByBatch(
            plantKey,
            wksToBeUpdated,
          ),
        logOperationInfo,
        { plant: plantKey, wksToBeUpdatedLength: wksToBeUpdated.length },
      );
    } catch (error) {
      this.customLogger.error(
        `plant ${plantKey} - Failed to replace update ShopOrders to Cosmos: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { ShipmentApi } from 'src/api/shipment-api';
import { PlantHierarchyApi } from '@/api/plant-hierarchy-api';
import { AppLogger } from '@/common/logger/app-logger';
import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCacheShipment {
  public constructor(
    private readonly shipmentApi: ShipmentApi,
    private readonly plantHierarchyApi: PlantHierarchyApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheShipment(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'UpdateCacheShipment',
      plant: Number(plant),
      service: 'updateCacheShipment',
    };
    try {
      // Fetch customer description if customer code is provided
      const customerCodes = [
        ...new Set(
          shopOrders
            .map((shoporder) => shoporder?.customer)
            .filter(
              (customer): customer is string => typeof customer === 'string',
            ),
        ),
      ];
      const sapServer = await this.plantHierarchyApi.getSapServerByPlant(plant);
      const customerDesc = await this.getCustomerDesc(
        customerCodes,
        sapServer.sapServer as string,
      );
      for (const shopOrder of shopOrders) {
        shopOrder.customerDesc =
          shopOrder.customer && customerDesc[shopOrder.customer]
            ? customerDesc[shopOrder.customer]
            : '';
      }

      const outbounds = shopOrders
        .filter(
          (shoporder) =>
            shoporder.outbound !== null || shoporder.outbound === '',
        ) // Remove null customers
        .map((shoporder) => shoporder.outbound as string); // Extract outbound list
      // Fetch TPA code using the shipment API
      const responseInvoker =
        await this.shipmentApi.getTpaAssignmentDetailsByPlantAndMultipleOutbounds(
          plant,
          outbounds,
        );
      const tpaData = responseInvoker;
      for (const shopOrder of shopOrders) {
        const tpaResult = tpaData[0]?.[shopOrder.outbound];

        if (tpaResult) {
          shopOrder.tpaCode = tpaResult.tpaCode || '';
          shopOrder.tpaBeginPreparation = tpaResult.beginPrep || '';
          shopOrder.tpaEndPreparation = tpaResult.endPrep || '';
          shopOrder.truckDepartureTime = tpaResult.truckDeparture || '';
        } else {
          shopOrder.tpaCode = '';
          shopOrder.tpaBeginPreparation = '';
          shopOrder.tpaEndPreparation = '';
          shopOrder.tpaEndPreparation = '';
          shopOrder.truckDepartureTime = '';
        }
      }
      return shopOrders;
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} Error updateCacheShipment: ${error.message}`,
        context,
        error.stack,
      );
      return shopOrders; // Return undefined in case of an error
    }
  }

  public async getCustomerDesc(
    customerCodes: Array<string>,
    sapServer: string,
  ): Promise<Record<string, string>> {
    // Fetch customer description
    const responseInvoker = await this.shipmentApi.fetchCustomerByCodes(
      customerCodes,
      sapServer,
    );
    const data = responseInvoker;
    return data;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { TransferApi } from '@/api/transfer-api';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { TransferByContainerIdsResponseDto } from '@/dtos/transfer-by-container-ids-response.dto';
import { TransferByContainerIdsRequestDto } from '@/dtos/trasnfer-by-container-ids-request.dto';
import { ShopOrder } from '@/interface/shop-order';

/**
 * Initializes the label order list by categorizing shop orders into multiple and single label orders.
 * @param shopOrders - An array of shop orders to be categorized.
 * @returns An object containing two arrays: multipleLabelOrders and singleLabelOrders.
 */
function initLabelOrderList(shopOrders: Array<ShopOrder>): {
  labelOrders: Array<string>;
} {
  const labelOrders: Array<string> = [];

  for (const shoporder of shopOrders) {
    if (
      shoporder.relatedLabel &&
      shoporder.relatedLabel !== 'MULTIPLE' &&
      shoporder.relatedLabel !== 'NULL'
    ) {
      labelOrders.push(shoporder.relatedLabel);
    }
  }

  return { labelOrders };
}

@Injectable()
export class UpdateCacheTransfer {
  public constructor(
    private readonly transferApi: TransferApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async updateCacheTransfer(
    plant: string,
    shopOrders: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    const context: JobsLogContext = {
      method: 'UpdateCacheTransfer',
      plant: Number(plant),
      service: 'updateCacheTransfer',
    };
    try {
      const { labelOrders } = initLabelOrderList(shopOrders);

      const containerDataLabel = await this._getTransferDetailsByContainers(
        plant,
        labelOrders,
      );
      const updatedShopOrder = shopOrders;
      if (containerDataLabel) {
        for (const shopOrder of updatedShopOrder) {
          if (
            shopOrder.relatedLabel !== 'MULTIPLE' &&
            shopOrder.relatedLabel !== 'NULL' &&
            containerDataLabel[shopOrder.relatedLabel]
          ) {
            shopOrder.dateTransfer =
              containerDataLabel[shopOrder.relatedLabel].createdOn;
            shopOrder.huCurrentStorageLocation =
              containerDataLabel[shopOrder.relatedLabel].destinationLocation;
          }
        }
      }
      return updatedShopOrder;
    } catch (error) {
      this.customLogger.error(
        `Plant ${plant} Error updateCacheTransfer: ${error.message}`,
        context,
        error.stack,
      );
      return shopOrders; // Return undefined in case of an error
    }
  }

  private async _getTransferDetailsByContainers(
    plant: string,
    labelOrders: Array<string>,
  ): Promise<Record<string, TransferByContainerIdsResponseDto>> {
    const logOperationInfo = {
      name: 'getTransferDetailsByContainers',
      srcLocation: 'updateCacheContainer',
    };
    const requestDto = new TransferByContainerIdsRequestDto();
    requestDto.plant = Number(plant);
    requestDto.containerIds = labelOrders;
    let containerDataMultipleLabel: Record<
      number,
      TransferByContainerIdsResponseDto
    > = {};
    if (labelOrders.length > 0) {
      containerDataMultipleLabel =
        (await execAndLog(
          this.customLogger,
          () => this.transferApi.fetchTransferDetailsByContainers(requestDto),
          logOperationInfo,
          { containerDataMultipleLabel },
        )) || {};
    }
    return containerDataMultipleLabel;
  }
}

