import { ShopOrder } from '@/interface/shop-order';

@Injectable()
export class UpdateCosmosStructure {
  private readonly processDatetimeto: string | undefined = undefined;

  private readonly scriptMode: string | undefined = undefined;

  private readonly slectedPlant: number | undefined = undefined;

  private readonly processDatetimeFrom: string | undefined = undefined;

  public constructor(
    private readonly cosmosDabaseService: CosmosDatabaseService,
    private readonly orderApi: OrderApi,
    private readonly plantHierarchyApi: PlantHierarchyApi,
    private readonly updateCosmosStructureJobConfigService: UpdateCosmosStructureJobConfigService,
    private readonly customLogger: AppLogger,
    private readonly shipmentApi: ShipmentApi,
    private readonly masterApi: MasterApi,
    private readonly productionApi: ProductionApi,
    private readonly transferApi: TransferApi,
    private readonly sharedCacheUpdateService: SharedCacheUpdateService,
  ) {
    const plantValue = Number(updateCosmosStructureJobConfigService.plant);
    this.slectedPlant = Number.isFinite(plantValue) ? plantValue : undefined;
    this.scriptMode = updateCosmosStructureJobConfigService.mode;
    this.processDatetimeto =
      updateCosmosStructureJobConfigService.processDatetimeto === ''
        ? new Date().toISOString()
        : new Date(
            updateCosmosStructureJobConfigService.processDatetimeto,
          ).toISOString();

    this.processDatetimeFrom =
      updateCosmosStructureJobConfigService.processDatetimeFrom === ''
        ? new Date(
            Date.now() -
              Number(updateCosmosStructureJobConfigService.processingPeriod) *
                60 *
                60 *
                1000,
          ).toISOString()
        : new Date(
            updateCosmosStructureJobConfigService.processDatetimeFrom,
          ).toISOString();

    this.orderApi.setUseAxios(true);
    this.shipmentApi.setUseAxios(true);
    this.masterApi.setUseAxios(true);
    this.plantHierarchyApi.setUseAxios(true);
    this.masterApi.setUseAxios(true);
    this.productionApi.setUseAxios(true);
    this.transferApi.setUseAxios(true);
  }

  public async updateCosmosStructure(): Promise<void> {
    await (this.scriptMode === 'FULL'
      ? this.fullSyncMode()
      : this.incrimentSyncMode());
  }

  private async fetchAllRelatedData(
    plant: number,
    materialIds: Array<string>,
    relatedOrders: Array<string>,
  ): Promise<{
    sebango: Record<string, string> | undefined;
    minSeqNumbers: Record<string, string> | undefined;
  }> {
    const sebango = await this.orderApi.getSebangoByMaterialDtlByIds({
      plant,
      materialIds,
    });

    const minSeqNumbers = await this.orderApi.fetchMinSeqNumList(
      plant,
      relatedOrders,
    );

    return { sebango, minSeqNumbers };
  }

  public async fullSyncMode(): Promise<void> {
    const context: JobsLogContext = {
      method: 'fullSyncMode',
      service: 'UpdateCosmosStructure',
    };
    try {
      const ordersCountByPlant =
        await this.orderApi.getShopOrdersCountByPlantList(this.slectedPlant);
      const chunkSize = Number(
        this.updateCosmosStructureJobConfigService.chunk,
      );
      if (ordersCountByPlant) {
        const processedPlantList = Object.keys(ordersCountByPlant).map(Number);
        const plants = Object.entries(ordersCountByPlant);
        if (processedPlantList.length === 0 && this.slectedPlant) {
          await this.deleteClosedShopOrders(this.slectedPlant);
        }
        await pMap(
          plants,
          async ([plantString, ordersCount]) => {
            const plant = Number(plantString);

            await this.deleteClosedShopOrders(plant);

            const plantConfig =
              await this.orderApi.fetchPlantConfigOrder(plant);
            const toleranceValueWk = plantConfig?.toleranceValueWk ?? 0;

            const totalChunks = Math.ceil(ordersCount / chunkSize);
            const chunks = Array.from(
              { length: totalChunks },
              (_, index) => index,
            );

            // Process all chunks for this plant using p-map instead of a for loop
            await pMap(
              chunks,
              async (chunk) => {
                const offset = chunk * chunkSize;
                await this.updateOrInsertShopOrders(
                  plant,
                  chunkSize,
                  offset,
                  toleranceValueWk,
                );
              },
              { concurrency: 1 }, // Or higher if you want to parallelize chunks
            );
          },
          { concurrency: 1 }, // Only 1 plant at a time
        );
      }
    } catch (error) {
      this.customLogger.error(
        'Failed to process orders by plant',
        context,
        error,
      );
      throw error; // Re-throw if you want upstream code to know
    }
  }

  private async deleteClosedShopOrders(
    plant: number,
    processDatetimeFrom: string | undefined = undefined,
    processDatetimeTo: string | undefined = undefined,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteClosedShopOrders',
      plant,
      service: 'UpdateCosmosStructure',
    };

    try {
      // Fetch closed shop order IDs from the API
      const closedShopOrderIds = await (this.scriptMode === 'INCREMENT' &&
      processDatetimeFrom &&
      processDatetimeTo
        ? this.orderApi.getClosedShopOrderIds(
            plant,
            new Date(processDatetimeFrom),
            new Date(processDatetimeTo),
          )
        : this.orderApi.getClosedShopOrderIds(plant));

      if (!closedShopOrderIds?.length) {
        return;
      }

      // Delegate to the Cosmos DB deletion method
      await this.cosmosDabaseService.deleteIfExistsByIds(
        closedShopOrderIds,
        plant,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to delete closed shop orders for plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  private async updateOrInsertShopOrders(
    plant: number,
    chunkSize: number,
    offset: number,
    toleranceValueWk: number,
  ): Promise<void> {
    // Fetch paginated shop orders
    const orders = await (this.scriptMode === 'FULL'
      ? this.orderApi.getPaginatedShopOrders(Number(plant), chunkSize, offset)
      : this.orderApi.fetchNotClosedOrdersByDate(
          plant,
          this.processDatetimeFrom,
          this.processDatetimeto,
        ));

    if (!orders) {
      return;
    }

    const { materialIds, pickingOrderIds, relatedOrders } =
      extractUniqueValues(orders);
    const etag = await this.cosmosDabaseService.getEtagsByIds(
      pickingOrderIds,
      plant,
    );
    const { sebango, minSeqNumbers } = await this.fetchAllRelatedData(
      plant,
      materialIds,
      relatedOrders,
    );

    let updatedOrders = [];
    let addOrders = [];
    for (const order of Object.values(orders)) {
      const updatedOrder = createUpdatedOrder(order, toleranceValueWk);
      updatedOrder.sebango = sebango?.[order.material] ?? '';
      updatedOrder.seqnum = minSeqNumbers?.[order.relatedOrder] ?? '';
      if (etag?.[updatedOrder.pickingOrderId]) {
        updatedOrder.etag = etag[updatedOrder.pickingOrderId];
        updatedOrders.push(updatedOrder);
      } else {
        addOrders.push(updatedOrder);
      }
    }
    updatedOrders = await this.updateCacheForOrder(
      String(plant),
      updatedOrders,
    );
    addOrders = await this.updateCacheForOrder(String(plant), addOrders);
    await this.cosmosDabaseService.updateWithBatch(updatedOrders);
    await this.cosmosDabaseService.insertWithBatch(addOrders);
  }

  public async incrimentSyncMode(): Promise<void> {
    const context: JobsLogContext = {
      method: 'incrimentSyncMode',
      service: 'UpdateCosmosStructure',
    };
    try {
      const plantIds = this.slectedPlant
        ? [this.slectedPlant]
        : await this.plantHierarchyApi.getAllPlantIds();

      const chunkSize = Number(
        this.updateCosmosStructureJobConfigService.chunk,
      );
      if (plantIds) {
        await pMap(
          plantIds,
          async (plantId) => {
            await this.deleteClosedShopOrders(
              plantId,
              this.processDatetimeFrom,
              this.processDatetimeto,
            );

            const plantConfig =
              await this.orderApi.fetchPlantConfigOrder(plantId);
            const toleranceValueWk = plantConfig?.toleranceValueWk ?? 0;

            await this.updateOrInsertShopOrders(
              plantId,
              chunkSize,
              0,
              toleranceValueWk,
            );
          },
          { concurrency: 1 }, // Or increase if you're okay with parallel processing
        );
      }
    } catch (error) {
      this.customLogger.error(
        'Failed to process orders by plant',
        context,
        error,
      );
      throw error; // Re-throw if you want upstream code to know
    }
  }

  public async updateCacheForOrder(
    plant: string,
    shopOrderResultsBuffer: Array<ShopOrder>,
  ): Promise<Array<ShopOrder>> {
    return this.sharedCacheUpdateService.updateAllCaches(
      plant,
      shopOrderResultsBuffer,
    );
  }
}

import { parentPort, workerData } from 'node:worker_threads';
import { JobsLogContext } from '@mesx/common-lib';
import { ConfigService } from '@nestjs/config';
import { DaprClient } from 'dapr-client';
import { OrderApi } from '@/api/order-api';
import { ProductionApi } from '@/api/production-api';
import { ShipmentApi } from '@/api/shipment-api';
import { TransferApi } from '@/api/transfer-api';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { AppConfigInitialConfigService } from '@/config/app-config/app-config-initial-config.service';
import { AppConfigService } from '@/config/app-config/app-config.service';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { LoggerConfigService } from '@/config/logger/logger-config.service';
import { processQueueMessages } from '@/helpers/queues/process-queue-message';
import { getQueuedMessages } from '@/helpers/queues/read-cache-queue';
import { instantiateUpdateCacheSequentially } from '@/helpers/updates/instantiate-update-cache-sequentially';
import { CacheResult } from '@/interface/cache-result';
import { CacheTask } from '@/interface/cache-task';
import {
  OrderResponse,
  PickingOrderList,
} from '@/interface/picking-order-list';

/**
 * Worker function to process data from the cache queue
 *@param data - data to process
 */
export async function processData(data: CacheTask): Promise<void> {
  const configService = new ConfigService();
  const appConfigIntialConfigService = new AppConfigInitialConfigService(
    configService,
  );
  const appConfig = new AppConfigService(appConfigIntialConfigService);
  const loggerConfigService = new LoggerConfigService(configService, appConfig);
  const customLogger = new AppLogger(loggerConfigService);
  const config = workerData?.config || {};
  await customLogger.init(config.logLevel);
  const context: JobsLogContext = {
    method: 'processData',
    plant: data.plant,
    service: 'WorkerTs',
  };

  const startTime = Date.now();
  const logOperationInfo = {
    name: '',
    srcLocation: 'processData',
  };
  const logOperationDetail = {
    data,
  };
  try {
    const daprConfigService = new DaprConfigService(
      configService,
      customLogger,
    );
    const daprClient = new DaprClient();

    const orderApi = new OrderApi(daprClient, daprConfigService, customLogger);
    const shipmentApi = new ShipmentApi(
      daprClient,
      daprConfigService,
      customLogger,
    );

    const productionApi = new ProductionApi(
      daprClient,
      daprConfigService,
      customLogger,
    );
    const transferApi = new TransferApi(
      daprClient,
      daprConfigService,
      customLogger,
    );

    const eventhub = new EventhubService(
      configService,
      customLogger,
      appConfig,
    );

    const updateCache = await instantiateUpdateCacheSequentially(daprClient);

    const publishMessageService = new PublishMessageService(
      daprClient,
      eventhub,
      customLogger,
    );
    const eventhubService = new EventhubService(
      configService,
      customLogger,
      appConfig,
    ); // Read the queue
    const {
      queueMessages,
      queueMessagesTpa,
      queueMessagesWkFromContainer,
      queueMessagesWkFromTransfer,
    } = await getQueuedMessages(customLogger, data);

    const pickingData: Array<PickingOrderList> = [];

    if (
      queueMessages.length > 0 ||
      queueMessagesTpa.length > 0 ||
      queueMessagesWkFromContainer.length > 0 ||
      queueMessagesWkFromTransfer.length > 0
    ) {
      await processQueueMessages(
        customLogger,
        queueMessages,
        queueMessagesTpa,
        queueMessagesWkFromContainer,
        queueMessagesWkFromTransfer,
        orderApi,
        shipmentApi,
        productionApi,
        transferApi,
        updateCache,
      );
    }

    // Fetch orders by date
    const updateTime = data.updateTime
      ? new Date(data.updateTime).getTime()
      : Date.now();

    const updateDurationInMs = Number(data.updateDuration) * 1000;

    const estimatedTime = updateTime - updateDurationInMs - 30 * 1000;

    const estimatedDate = new Date(estimatedTime);
    // Continue processing with additional updates
    logOperationInfo.name = 'fetchOrdersByDate';
    const responseInvoker: OrderResponse | undefined = await execAndLog(
      customLogger,
      () => orderApi.fetchOrdersByDate(data.plant, estimatedDate),
      logOperationInfo,
      logOperationDetail,
    );
    const result = responseInvoker?.result;
    const dateHeader =
      responseInvoker?.headers['date'] ?? new Date().toUTCString();
    const serverUTCDateTime = new Date(dateHeader);

    if ((result?.length === 0 || !result) && pickingData.length === 0) {
      const publishTime = new Date(data.publishTime);
      const resultCache: CacheResult = {
        orchestratorPublishTime: data.publishTime,
        plant: data.plant,
        updateDuration: Math.floor((Date.now() - publishTime.getTime()) / 1000),
        updateTime: serverUTCDateTime
          ? new Date(serverUTCDateTime)
          : new Date(),
        uuid: data.uuid,
      };
      logOperationInfo.name = 'publishMessage';
      await execAndLog(
        customLogger,
        () =>
          publishMessageService.publishMessage(
            eventhubService.topicResults,
            resultCache,
          ),
        logOperationInfo,
        logOperationDetail,
      );
      return;
    }

    if (result) {
      pickingData.push(...result);
    }
    // Await updateCacheSequentially.updateCacheSequentially(pickingData);

    logOperationInfo.name = 'updateCacheSequentially';
    await execAndLog(
      customLogger,
      async () => {
        await updateCache.updateCacheSequentially(pickingData);
      },
      logOperationInfo,
      logOperationDetail,
    );

    const publishTime = new Date(data.publishTime);

    const resultCache: CacheResult = {
      orchestratorPublishTime: data.publishTime,
      plant: data.plant,
      updateDuration: Math.floor((Date.now() - publishTime.getTime()) / 1000),
      updateTime: serverUTCDateTime ? new Date(serverUTCDateTime) : new Date(),
      uuid: data.uuid,
    };

    logOperationInfo.name = 'publishMessage';
    await execAndLog(
      customLogger,
      () =>
        publishMessageService.publishMessage(
          eventhubService.topicResults,
          resultCache,
        ),
      logOperationInfo,
      logOperationDetail,
    );
  } catch (error) {
    customLogger.error(
      ` Plant ${data.plant} Error processing message: ${error.message}`,
      context,
      error.stack,
    );
  }

  logOperationInfo.name = 'processData runtime';
  await execAndLog(
    customLogger,
    async () => {},
    logOperationInfo,
    logOperationDetail,
    startTime,
  );
}

parentPort?.on('message', async (data) => {
  // Example processing function
  await processData(data);
});

import { Module } from '@nestjs/common';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { Piscina } from 'piscina';
import { WorkersService } from './workers.service';
import { ApiModule } from '@/api/api.module';
import { LoggerConfigModule } from '@/config/logger/logger-config.module';
import { LoggerConfigService } from '@/config/logger/logger-config.service';
import { ThreadConfigModule } from '@/config/thread-config/thread-config.module';
import { ThreadConfigService } from '@/config/thread-config/thread-config.service';

@Module({
  exports: [WorkersService],
  imports: [ConfigModule, ApiModule, ThreadConfigModule, LoggerConfigModule],
  providers: [
    WorkersService,
    {
      inject: [ThreadConfigService, LoggerConfigService],
      provide: 'Piscina',
      useFactory: async (
        threadConfigService: ThreadConfigService,
        loggerConfigService: LoggerConfigService,
      ): Promise<Piscina> => {
        const filePath = `${process.cwd()}/dist/workers/worker.js`; // Path to worker file
        const logLevel = await loggerConfigService.pickingMpLogLevel();
        return new Piscina({
          filename: filePath,
          maxThreads: await threadConfigService.maxThreads(),
          workerData: { config: { logLevel } },
        });
      },
    },
    ConfigService,
  ],
})
export class WorkersModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Inject, Injectable } from '@nestjs/common';
import { Piscina } from 'piscina';
import { AppLogger } from '@/common/logger/app-logger';
import { CacheTask } from '@/interface/cache-task';

@Injectable()
export class WorkersService {
  public constructor(
    @Inject('Piscina') private readonly piscina: Piscina, // Inject the Piscina instance
    private readonly customLogger: AppLogger,
  ) {}

  public async runTask(data: CacheTask): Promise<void> {
    const context: JobsLogContext = {
      method: 'runTask',
      plant: data.plant,
      service: 'WorkersService',
    };
    try {
      await this.piscina.run(data, { name: 'processData' });
    } catch (error) {
      this.customLogger.error(
        `Error initializing WorkersService ${data.plant} : ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

